package com.balance.app.work;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.math.*;import java.time.*;
class WorkPayrollTest {
 @Test void fixedPauseAndNightShift(){assertEquals(450,WorkCalendarService.minutes(LocalTime.of(8,0),LocalTime.of(16,0)));assertEquals(450,WorkCalendarService.minutes(LocalTime.of(22,0),LocalTime.of(6,0)));assertThrows(RuntimeException.class,()->WorkCalendarService.minutes(LocalTime.of(8,0),LocalTime.of(8,30)));assertThrows(RuntimeException.class,()->WorkCalendarService.minutes(LocalTime.of(8,0),LocalTime.of(8,0)));}
 @Test void netIncludesTaxAndAllEmployeeContributions(){var r=GermanPayroll.estimate(new BigDecimal("3000.00"),YearMonth.of(2026,11),LocalDate.of(1995,1,1),false,0,0,new BigDecimal("2.9"));assertNotNull(r.net());assertEquals(new BigDecimal("279.00"),r.pension());assertEquals(new BigDecimal("39.00"),r.unemployment());assertEquals(new BigDecimal("262.50"),r.health());assertEquals(new BigDecimal("72.00"),r.care());assertEquals(new BigDecimal("3000.00"),r.net().add(r.tax()).add(r.solidarity()).add(r.pension()).add(r.unemployment()).add(r.health()).add(r.care()));assertTrue(r.tax().signum()>0);}
 @Test void childAndSaxonyChangeCareContributions(){var month=YearMonth.of(2026,11);var birth=LocalDate.of(1995,1,1);var g=new BigDecimal("3000");var extra=new BigDecimal("2.9");assertEquals(new BigDecimal("87.00"),GermanPayroll.estimate(g,month,birth,true,0,0,extra).care());assertEquals(new BigDecimal("46.50"),GermanPayroll.estimate(g,month,birth,false,2,2,extra).care());assertEquals(new BigDecimal("54.00"),GermanPayroll.estimate(g,month,LocalDate.of(2003,11,15),false,0,0,extra).care());}
 @Test void ageReliefRequiresItsOwnParameters(){assertNull(GermanPayroll.estimate(new BigDecimal("3000"),YearMonth.of(2026,11),LocalDate.of(1961,12,15),false,0,0,new BigDecimal("2.9")).net());}
 @Test void ordinaryEmploymentBelowTwoThousandStillHasNetEstimate(){
  for(String amount:new String[]{"122.64","603.00","1500.00","2000.00","2000.01"}){var gross=new BigDecimal(amount);var r=GermanPayroll.estimate(gross,YearMonth.of(2026,11),LocalDate.of(1995,1,1),false,0,0,new BigDecimal("2.9"));assertNotNull(r.net());assertTrue(r.net().signum()>=0);assertTrue(r.net().compareTo(gross)<=0);assertEquals(gross,r.net().add(r.tax()).add(r.solidarity()).add(r.pension()).add(r.unemployment()).add(r.health()).add(r.care()));}
  var low=GermanPayroll.estimate(new BigDecimal("1500.00"),YearMonth.of(2026,11),LocalDate.of(1995,1,1),false,0,0,new BigDecimal("2.9"));assertEquals(new BigDecimal("139.50"),low.pension());assertEquals(new BigDecimal("19.50"),low.unemployment());assertEquals(new BigDecimal("131.25"),low.health());assertEquals(new BigDecimal("36.00"),low.care());
 }
 @Test void unavailableYearHasExplicitReasonAndNoInventedAmounts(){var r=GermanPayroll.estimate(new BigDecimal("3000"),YearMonth.of(2027,1),LocalDate.of(1995,1,1),false,0,0,new BigDecimal("2.9"));assertEquals("UNSUPPORTED_YEAR",r.status());assertNull(r.taxYear());assertNull(r.net());assertNull(r.tax());assertNull(r.health());assertTrue(r.note().contains("2027"));var missing=GermanPayroll.estimate(new BigDecimal("3000"),YearMonth.of(2026,1),null,false,0,0,new BigDecimal("2.9"));assertEquals("SETTINGS_REQUIRED",missing.status());assertEquals(2026,missing.taxYear());}
 @Test void unsupportedCasesAreNeverInvented(){assertNull(GermanPayroll.estimate(new BigDecimal("3000"),YearMonth.of(2027,1),LocalDate.of(1995,1,1),false,0,0,new BigDecimal("2.9")).net());assertNull(GermanPayroll.estimate(new BigDecimal("3000"),YearMonth.of(2026,11),null,false,0,0,new BigDecimal("2.9")).net());}
}
